// lib/hotels.ts

export type SearchParams = {
  term: string;
  lat?: string;
  lng?: string;
  checkIn: string; // YYYY-MM-DD or ""
  checkOut: string; // YYYY-MM-DD or ""
  adults: number;
  children: number;
  rooms: number;
};

const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;

function isIsoDate(value: string): boolean {
  return ISO_DATE.test(value) && !Number.isNaN(new Date(`${value}T00:00:00Z`).getTime());
}

/**
 * Turns Next.js `searchParams` into a typed, validated object.
 * Invalid or missing values fall back to safe defaults.
 */
export function parseSearchParams(
  raw: Record<string, string | string[] | undefined>
): SearchParams {
  const get = (key: string): string | undefined => {
    const v = raw[key];
    return Array.isArray(v) ? v[0] : v;
  };

  const int = (key: string, fallback: number, min: number, max: number): number => {
    const n = Number(get(key));
    return Number.isInteger(n) && n >= min && n <= max ? n : fallback;
  };

  const date = (key: string): string => {
    const v = get(key) ?? "";
    return isIsoDate(v) ? v : "";
  };

  const checkIn = date("checkIn");
  const checkOut = date("checkOut");

  return {
    term: get("term") ?? "",
    lat: get("lat"),
    lng: get("lng"),
    // both dates are required, and check-out must be after check-in
    checkIn: checkIn && checkOut && checkOut > checkIn ? checkIn : "",
    checkOut: checkIn && checkOut && checkOut > checkIn ? checkOut : "",
    adults: int("adults", 1, 1, 30),
    children: int("children", 0, 0, 10),
    rooms: int("rooms", 1, 1, 9),
  };
}

/** Number of nights between two YYYY-MM-DD dates (minimum 1). */
export function countNights(checkIn: string, checkOut: string): number {
  const diff =
    (new Date(`${checkOut}T00:00:00Z`).getTime() - new Date(`${checkIn}T00:00:00Z`).getTime()) /
    86_400_000;
  return Number.isFinite(diff) && diff > 0 ? Math.round(diff) : 1;
}

/** "Fri, Nov 6, 2026" – or "-" for empty / invalid input. */
export function formatDate(iso: string): string {
  const d = new Date(`${iso}T00:00:00Z`);
  if (!iso || Number.isNaN(d.getTime())) return "-";
  return d.toLocaleDateString("en-US", {
    weekday: "short",
    month: "short",
    day: "numeric",
    year: "numeric",
    timeZone: "UTC",
  });
}